}

{
  "items": [
    {
      "id": "AJCR.w4-rep.datum.dat-d.ddr.certificate.cert-relocalize",
      "title": "Cert-relocalize: restate IsLocallyCertified/DivFamZar to quantify over the coordinate twist",
      "projects": [
